-- Sales: base demand x ISO-weekday multiplier (weekend spike) x per-day noise (80-120%).
-- The last row (idx 91) is "today so far" at 70% of a full day.
INSERT INTO sales_daily (tenant_id, sale_date, sku, qty_sold, revenue_vnd, revenue_display)
SELECT tenant_id, sale_date, sku, qty, qty * price, round(qty * price / 25000.0, 2)
FROM (
  SELECT 'c0ffee00-0000-4000-8000-000000000001'::uuid AS tenant_id,
         (SELECT d FROM demo_anchor) - (91 - n.idx)::int AS sale_date,
         p.sku, p.price,
         GREATEST(0, round(p.base
           * (ARRAY[0.9, 0.85, 0.9, 0.95, 1.1, 1.45, 1.35])[extract(isodow FROM (SELECT d FROM demo_anchor) - (91 - n.idx)::int)::int]
           * n.noise / 100.0
           * CASE WHEN n.idx = 91 THEN 0.7 ELSE 1 END)) AS qty
  FROM demo_products p
  CROSS JOIN LATERAL unnest(p.noise) WITH ORDINALITY AS n(noise, idx)
) s;

